-- Generated by `npm run gen:missions` from lib/plan-engine/missions.ts. Don't edit by hand.
on conflict (id) do update set
  pillar = excluded.pillar, title = excluded.title, how_to = excluded.how_to,
  minutes = excluded.minutes, cost = excluded.cost, needs = excluded.needs,
  difficulty = excluded.difficulty, archetypes = excluded.archetypes, act = excluded.act,
  tags = excluded.tags, pack = excluded.pack, active = true;

-- Missions removed from the library stay for history but are no longer picked.
update public.mission_library set active = false where id not in ('car-01', 'car-02', 'car-03', 'car-04', 'car-05', 'car-06', 'car-07', 'car-08', 'car-09', 'car-10', 'car-11', 'car-12', 'car-13', 'car-14', 'car-15', 'car-16', 'car-17', 'car-18', 'car-19', 'car-20', 'car-21', 'car-22', 'car-23', 'car-24', 'car-25', 'car-26', 'car-27', 'car-28', 'car-29', 'car-30', 'bod-01', 'bod-02', 'bod-03', 'bod-04', 'bod-05', 'bod-06', 'bod-07', 'bod-08', 'bod-09', 'bod-10', 'bod-11', 'bod-12', 'bod-13', 'bod-14', 'bod-15', 'bod-16', 'bod-17', 'bod-18', 'bod-19', 'bod-20', 'bod-21', 'bod-22', 'bod-23', 'bod-24', 'bod-25', 'bod-26', 'bod-27', 'bod-28', 'bod-29', 'bod-30', 'min-01', 'min-02', 'min-03', 'min-04', 'min-05', 'min-06', 'min-07', 'min-08', 'min-09', 'min-10', 'min-11', 'min-12', 'min-13', 'min-14', 'min-15', 'min-16', 'min-17', 'min-18', 'min-19', 'min-20', 'min-21', 'min-22', 'min-23', 'min-24', 'min-25', 'min-26', 'min-27', 'min-28', 'min-29', 'min-30', 'mon-01', 'mon-02', 'mon-03', 'mon-04', 'mon-05', 'mon-06', 'mon-07', 'mon-08', 'mon-09', 'mon-10', 'mon-11', 'mon-12', 'mon-13', 'mon-14', 'mon-15', 'mon-16', 'mon-17', 'mon-18', 'mon-19', 'mon-20', 'mon-21', 'mon-22', 'mon-23', 'mon-24', 'mon-25', 'mon-26', 'mon-27', 'mon-28', 'mon-29', 'mon-30');
