insert into public.mission_library
  (id, pillar, title, how_to, minutes, cost, needs, difficulty, archetypes, act, tags, pack)
values
  ('car-01', 'career', 'Record a 60-second self-introduction', 'Record it on your phone, replay it once, and fix one thing: pace, filler words or where you look.', 5, 'free', 'none', 1, array['grinder', 'climber']::text[], 1, '{}'::text[], null),
  ('car-02', 'career', 'Write your resume headline in one line', 'The role you want plus your strongest proof, like "Final-year CSE, built two Android apps".', 5, 'free', 'none', 1, array['grinder', 'climber']::text[], 1, '{}'::text[], null),
  ('car-03', 'career', 'Explain one project in three sentences', 'The problem, what you built, what happened. Say it aloud until it fits in 30 seconds.', 5, 'free', 'none', 1, array['grinder', 'climber', 'founder']::text[], 1, '{}'::text[], null),
  ('car-04', 'career', 'Read one job post and pick three must-have skills', 'Choose a post for the role you want. Write the three skills it repeats most.', 5, 'free', 'none', 1, array['grinder', 'climber']::text[], 1, '{}'::text[], null),
  ('car-05', 'career', 'List 10 companies you''d like to work for', 'Five dream companies and five realistic ones in your city. Note one role at each.', 10, 'free', 'none', 1, array['grinder', 'climber']::text[], 1, array['planning']::text[], null),
  ('car-06', 'career', 'Set up a job-search tracker', 'A simple table in notes: company, role, date applied, status, next step.', 10, 'free', 'none', 1, array['grinder', 'climber']::text[], 1, array['planning']::text[], null),
  ('car-07', 'career', 'Fix your LinkedIn headline', 'Say what you do and what you want next in plain words. No buzzwords.', 10, 'free', 'none', 1, array['grinder', 'climber', 'founder']::text[], 1, '{}'::text[], null),
  ('car-08', 'career', 'Solve one aptitude set of 10 questions', 'Quant, logical or verbal. Time yourself, then note the question type you missed most.', 20, 'free', 'none', 2, array['grinder']::text[], 1, '{}'::text[], null),
  ('car-09', 'career', 'Solve 2 easy coding problems', 'Array or string problems on any free practice site. Write your approach before the code.', 30, 'free', 'laptop', 2, array['grinder', 'climber']::text[], 1, '{}'::text[], null),
  ('car-10', 'career', 'Write resume version 1', 'One page, one column: education, skills, two projects, contact. A plain format that hiring software can read.', 45, 'free', 'laptop', 3, array['grinder', 'climber']::text[], 1, '{}'::text[], null),
  ('car-11', 'career', 'Send one senior a specific question on LinkedIn', 'One clear question about their work, not a request for a job. Thank them either way.', 5, 'free', 'none', 1, array['grinder', 'climber', 'founder']::text[], 2, '{}'::text[], null),
  ('car-12', 'career', 'Rewrite one resume bullet with a number', '"Built a library app" becomes "Built a library app used by 120 students in my hostel".', 5, 'free', 'none', 1, array['grinder', 'climber']::text[], 2, '{}'::text[], null),
  ('car-13', 'career', 'Answer "Why should we hire you?" in three lines', 'One skill, one proof, one reason you want this role. Read it aloud once.', 5, 'free', 'none', 2, array['grinder', 'climber']::text[], 2, '{}'::text[], null),
  ('car-14', 'career', 'Check one job alert or off-campus drive', 'Open your saved alerts, pick one that fits, and add it to your tracker with a date.', 5, 'free', 'none', 1, array['grinder']::text[], 2, '{}'::text[], null),
  ('car-15', 'career', 'Apply to 3 roles with a tailored first line', 'For each one, write a first line that names the role and your closest proof. Log them in your tracker.', 30, 'free', 'none', 2, array['grinder', 'climber']::text[], 2, '{}'::text[], null),
  ('car-16', 'career', 'Practise 5 common HR questions aloud', 'Strengths, weaknesses, a conflict, a failure, where you see yourself. Short, true answers.', 10, 'free', 'none', 2, array['grinder', 'climber']::text[], 2, '{}'::text[], null),
  ('car-17', 'career', 'Do a 15-question aptitude sprint', 'One minute per question. Review every wrong answer before you stop.', 20, 'free', 'none', 2, array['grinder']::text[], 2, '{}'::text[], null),
  ('car-18', 'career', 'Run a mock interview with a friend', 'Swap roles, 15 minutes each, using real questions for your target role. Ask for one honest note.', 30, 'free', 'none', 3, array['grinder', 'climber']::text[], 2, '{}'::text[], null),
  ('car-19', 'career', 'Solve one medium coding problem', 'Talk through the brute force first, then improve it. Note the pattern you used.', 45, 'free', 'laptop', 3, array['grinder', 'climber']::text[], 2, '{}'::text[], null),
  ('car-20', 'career', 'Write one STAR story', 'Situation, task, action, result for a time you fixed a problem. Keep it under a minute.', 10, 'free', 'none', 2, array['grinder', 'climber']::text[], 2, '{}'::text[], null),
  ('car-21', 'career', 'Save one interview question you can''t answer yet', 'Write it down now and find a good answer before tomorrow.', 5, 'free', 'none', 1, array['grinder', 'climber']::text[], 3, '{}'::text[], null),
  ('car-22', 'career', 'Thank someone who helped your career', 'A short, specific message: what they did and how it helped.', 5, 'free', 'none', 1, '{}'::text[], 3, '{}'::text[], null),
  ('car-23', 'career', 'Give your self-introduction without notes', 'Record it once. If you stumble, start again from the top.', 5, 'free', 'none', 2, array['grinder', 'climber']::text[], 3, '{}'::text[], null),
  ('car-24', 'career', 'Explain a core subject topic in 2 minutes', 'DBMS, operating systems, networks or your main subject. Teach it to an empty room.', 10, 'free', 'none', 2, array['grinder']::text[], 3, '{}'::text[], null),
  ('car-25', 'career', 'Research one company before you apply', 'What they sell, who their customers are, and one recent piece of news.', 10, 'free', 'none', 2, array['grinder', 'climber']::text[], 3, '{}'::text[], null),
  ('car-26', 'career', 'Ask one employee for a referral the right way', 'Send the role link, two lines on why you fit, and your resume. Make it easy to say yes.', 10, 'free', 'none', 2, array['grinder', 'climber']::text[], 3, '{}'::text[], null),
  ('car-27', 'career', 'Ship one improvement to a portfolio project', 'Fix a bug, write the README or put it online. Make it something a recruiter can open.', 45, 'free', 'laptop', 3, array['grinder', 'climber', 'founder']::text[], 3, '{}'::text[], null),
  ('car-28', 'career', 'Take a timed mock test: aptitude plus coding', 'Sit it like the real thing, no breaks. Write down the two areas that cost you the most time.', 45, 'free', 'laptop', 3, array['grinder']::text[], 3, '{}'::text[], null),
  ('car-29', 'career', 'Know your salary range', 'Check the typical range for your role and city on two public sources. Write the number you''ll ask for.', 20, 'free', 'none', 2, array['climber']::text[], 3, '{}'::text[], null),
  ('car-30', 'career', 'Record a 2-minute project walkthrough', 'The problem, a quick demo, what you''d improve. Replay it and cut the filler.', 20, 'free', 'none', 3, array['grinder', 'climber', 'founder']::text[], 3, '{}'::text[], null),
  ('bod-01', 'body', '10-minute Surya Namaskar set', 'Move slowly with your breath. Stop if anything hurts.', 10, 'free', 'none', 1, array['warrior', 'phoenix']::text[], 1, array['energy']::text[], null),
  ('bod-02', 'body', 'Walk 6,000 steps; take one call on foot', 'Spread it over the day. Your phone''s step counter is enough.', 30, 'free', 'outdoors', 1, array['warrior']::text[], 1, array['energy']::text[], null),
  ('bod-03', 'body', 'Protein check: add eggs, paneer, dal or chana to two meals', 'Use what''s already in your kitchen or mess. No supplements needed.', 5, 'low', 'none', 1, array['warrior']::text[], 1, '{}'::text[], null),
  ('bod-04', 'body', 'Drink a glass of water before each meal', 'Three meals, three glasses. Keep a bottle where you can see it.', 5, 'free', 'none', 1, '{}'::text[], 1, array['energy']::text[], null),
  ('bod-05', 'body', '5-minute morning stretch', 'Neck, shoulders, hips and hamstrings. Gentle, no bouncing.', 5, 'free', 'none', 1, array['warrior', 'phoenix']::text[], 1, array['energy']::text[], null),
  ('bod-06', 'body', 'One round: 20 squats, 10 push-ups, 20-second plank', 'Knee push-ups are fine. Good form beats more reps.', 5, 'free', 'none', 1, array['warrior']::text[], 1, '{}'::text[], null),
  ('bod-07', 'body', 'Stand up and move for 2 minutes, four times today', 'Set a reminder every hour while you study or work. Walk, stretch or climb stairs.', 5, 'free', 'none', 1, '{}'::text[], 1, array['energy']::text[], null),
  ('bod-08', 'body', '20-minute no-equipment push and pull circuit', 'Push-ups, towel rows against a sturdy door, squats and a plank. Three rounds, rest as you need.', 20, 'free', 'none', 2, array['warrior']::text[], 1, '{}'::text[], null),
  ('bod-09', 'body', 'Gym: learn the squat, row and press with light weight', 'Three sets of 10 with a weight you could lift 15 times. Ask a trainer to check your form.', 45, 'free', 'gym', 2, array['warrior']::text[], 1, '{}'::text[], null),
  ('bod-10', 'body', 'Sleep 30 minutes earlier tonight', 'Set an alarm for bedtime, not just for waking up.', 5, 'free', 'none', 1, array['warrior', 'phoenix']::text[], 1, array['energy']::text[], null),
  ('bod-11', 'body', 'Brisk 20-minute walk', 'Fast enough that talking takes a little effort. Morning or evening.', 20, 'free', 'outdoors', 1, '{}'::text[], 2, array['energy']::text[], null),
  ('bod-12', 'body', 'Three rounds: 15 squats, 10 push-ups, 30-second plank', 'Rest a minute between rounds. Write down your total push-ups.', 10, 'free', 'none', 2, array['warrior']::text[], 2, '{}'::text[], null),
  ('bod-13', 'body', 'Plate check: half veg, quarter protein, quarter roti or rice', 'Look at one meal today and adjust it. No calorie counting.', 5, 'free', 'none', 1, '{}'::text[], 2, '{}'::text[], null),
  ('bod-14', 'body', 'Skip the lift wherever you can today', 'Stairs at college, work or home. Take them at your own pace.', 5, 'free', 'none', 1, '{}'::text[], 2, '{}'::text[], null),
  ('bod-15', 'body', 'Home leg day: lunges, squats and glute bridges', 'Three rounds of 12 each. Hold a water bottle in each hand if it feels easy.', 20, 'free', 'none', 2, array['warrior']::text[], 2, '{}'::text[], null),
  ('bod-16', 'body', '10-minute mobility for desk necks and backs', 'Chin tucks, shoulder rolls, cat-cow and a hip stretch. Slow and easy.', 10, 'free', 'none', 1, '{}'::text[], 2, array['energy']::text[], null),
  ('bod-17', 'body', 'Swap one packaged snack for fruit, roasted chana or curd', 'Just one swap today. Keep it simple and cheap.', 5, 'low', 'none', 1, '{}'::text[], 2, '{}'::text[], null),
  ('bod-18', 'body', 'Gym: full-body session, three lifts, three sets each', 'Squat or leg press, a row and a press. Log your weights so you can progress slowly.', 45, 'free', 'gym', 3, array['warrior']::text[], 2, '{}'::text[], null),
  ('bod-19', 'body', '30-minute walk or easy jog', 'Easy enough to talk in short sentences. Walk breaks are fine.', 30, 'free', 'outdoors', 2, array['warrior']::text[], 2, array['energy']::text[], null),
  ('bod-20', 'body', 'No screens 30 minutes before bed', 'Charge your phone away from your bed. Read, stretch or plan tomorrow instead.', 5, 'free', 'none', 1, array['phoenix']::text[], 2, array['energy', 'phone']::text[], null),
  ('bod-21', 'body', 'Push-up test: count your clean reps', 'One set to near failure with good form. Write the number and compare it with Week 1.', 5, 'free', 'none', 2, array['warrior']::text[], 3, '{}'::text[], null),
  ('bod-22', 'body', 'Five rounds of 30 seconds of high knees', 'Rest 30 seconds between rounds. March in place if your knees need it.', 5, 'free', 'none', 2, array['warrior']::text[], 3, array['energy']::text[], null),
  ('bod-23', 'body', '10-minute morning sunlight walk', 'Within an hour of waking. Leave your earphones in your pocket.', 10, 'free', 'outdoors', 1, array['phoenix']::text[], 3, array['energy']::text[], null),
  ('bod-24', 'body', 'Core finisher: plank, side planks and dead bugs', '30 seconds each, two rounds. Keep your lower back flat.', 10, 'free', 'none', 2, array['warrior']::text[], 3, '{}'::text[], null),
  ('bod-25', 'body', 'Hydration day: eight glasses of water', 'Tick them off in your notes. More if it''s hot or you trained.', 5, 'free', 'none', 1, '{}'::text[], 3, array['energy']::text[], null),
  ('bod-26', 'body', '30-minute home strength session', 'Push-ups, squats, lunges, towel rows and planks. Four rounds, rest as you need.', 30, 'free', 'none', 3, array['warrior']::text[], 3, '{}'::text[], null),
  ('bod-27', 'body', 'Prep tomorrow''s protein: soak chana or boil eggs', 'Ten minutes tonight saves you a fried snack tomorrow.', 10, 'low', 'none', 1, array['warrior']::text[], 3, '{}'::text[], null),
  ('bod-28', 'body', 'Gym: beat one lift from last week by a small step', 'One more rep or the smallest plate. Never at the cost of form.', 45, 'free', 'gym', 3, array['warrior']::text[], 3, '{}'::text[], null),
  ('bod-29', 'body', 'Play a sport outside for 30 minutes', 'Cricket, football, badminton or a long cycle. Anything that gets you moving with others.', 30, 'free', 'outdoors', 2, '{}'::text[], 3, array['energy']::text[], null),
  ('bod-30', 'body', '20-minute slow yoga flow', 'Follow a free beginner video or your own Surya Namaskar sets. Breathe through the nose.', 20, 'free', 'none', 2, array['warrior', 'phoenix']::text[], 3, array['energy']::text[], null),
  ('min-01', 'mind', 'No phone for the first 30 minutes after waking', 'Put your alarm across the room. Wash up, drink water and plan before you scroll.', 5, 'free', 'none', 1, array['phoenix']::text[], 1, array['phone']::text[], null),
  ('min-02', 'mind', 'Write tomorrow''s top 3 before sleeping', 'Three tasks, most important first. Keep the list where you''ll see it in the morning.', 5, 'free', 'none', 1, array['phoenix', 'grinder', 'climber']::text[], 1, array['planning']::text[], null),
  ('min-03', 'mind', '10 minutes on the task you''re avoiding, timer on', 'Just 10 minutes. Stop when the timer rings if you want to.', 10, 'free', 'none', 1, array['phoenix']::text[], 1, array['focus']::text[], null),
  ('min-04', 'mind', 'Turn off notifications for three apps', 'Start with the ones that pull you in most. Calls and messages from people can stay on.', 5, 'free', 'none', 1, array['phoenix']::text[], 1, array['phone']::text[], null),
  ('min-05', 'mind', 'Read 10 pages of a book', 'Any book you''d like to finish. Free e-books and library copies count.', 10, 'free', 'none', 1, '{}'::text[], 1, '{}'::text[], null),
  ('min-06', 'mind', 'Two-minute brain dump', 'Write everything on your mind, then circle one thing to do today.', 5, 'free', 'none', 1, array['phoenix']::text[], 1, array['focus', 'planning']::text[], null),
  ('min-07', 'mind', 'Box breathing: four rounds', 'In for 4, hold for 4, out for 4, hold for 4. Use it before an exam or a hard call.', 5, 'free', 'none', 1, '{}'::text[], 1, array['focus']::text[], null),
  ('min-08', 'mind', 'One 25-minute focus block, phone in another room', 'One task only. When your mind wanders, write the thought down and go back.', 30, 'free', 'none', 2, array['phoenix', 'grinder', 'climber']::text[], 1, array['phone', 'focus']::text[], null),
  ('min-09', 'mind', 'Plan your week in 10 minutes', 'Classes, work, deadlines and three things you want done by Sunday.', 10, 'free', 'none', 1, array['phoenix']::text[], 1, array['planning']::text[], null),
  ('min-10', 'mind', 'Check your screen time and set one app limit', 'Find your top app this week and set a daily limit a little below it.', 5, 'free', 'none', 1, array['phoenix']::text[], 1, array['phone']::text[], null),
  ('min-11', 'mind', 'Two 20-minute focus blocks with a short break', 'Phone in another room. Walk or drink water in the break, no scrolling.', 45, 'free', 'none', 3, array['phoenix', 'grinder', 'climber']::text[], 2, array['phone', 'focus']::text[], null),
  ('min-12', 'mind', 'Write one line: what went well today', 'Something small counts. Add it to your private journal in Me.', 5, 'free', 'none', 1, '{}'::text[], 2, '{}'::text[], null),
  ('min-13', 'mind', 'Eat one meal with no phone', 'Put it face down or in another room. Just eat, or talk to whoever''s with you.', 5, 'free', 'none', 1, array['phoenix']::text[], 2, array['phone']::text[], null),
  ('min-14', 'mind', 'Learn one new idea and explain it in your own words', 'Read or watch something for 10 minutes, then write 5 lines without looking.', 20, 'free', 'none', 2, '{}'::text[], 2, '{}'::text[], null),
  ('min-15', 'mind', 'Do the hardest task first', 'Before 11 am, give 20 minutes to the task you''d most like to skip.', 20, 'free', 'none', 2, array['phoenix']::text[], 2, array['focus']::text[], null),
  ('min-16', 'mind', '10-minute walk without your phone', 'Let your mind wander. Notice three things you usually miss.', 10, 'free', 'outdoors', 1, '{}'::text[], 2, array['phone', 'energy']::text[], null),
  ('min-17', 'mind', 'Swap 15 minutes of scrolling for reading', 'When you reach for a feed, open a book or a long article instead.', 20, 'free', 'none', 2, array['phoenix']::text[], 2, array['phone']::text[], null),
  ('min-18', 'mind', 'Name the worry, then the next small action', 'When you catch yourself overthinking, write the worry in one line and one action you can take today.', 5, 'free', 'none', 1, array['phoenix']::text[], 2, array['focus']::text[], null),
  ('min-19', 'mind', 'Tidy your study or work space for 10 minutes', 'Clear the desk, put away what you don''t need today, keep water within reach.', 10, 'free', 'none', 1, '{}'::text[], 2, '{}'::text[], null),
  ('min-20', 'mind', 'Weekly look-back in 10 minutes', 'What worked, what didn''t, and one change for next week.', 10, 'free', 'none', 1, array['phoenix', 'strategist']::text[], 2, array['planning']::text[], null),
  ('min-21', 'mind', 'Single-task for 45 minutes', 'One task, one tab, phone away. Note how far you got.', 45, 'free', 'none', 3, array['phoenix', 'grinder', 'climber']::text[], 3, array['phone', 'focus']::text[], null),
  ('min-22', 'mind', 'Say no to one thing that isn''t a priority', 'Politely and clearly. Use the time for something on your top 3.', 5, 'free', 'none', 2, '{}'::text[], 3, array['planning']::text[], null),
  ('min-23', 'mind', 'Teach someone one thing you learnt this week', 'A friend, sibling or classmate. Explaining it shows you what you really know.', 10, 'free', 'none', 2, '{}'::text[], 3, '{}'::text[], null),
  ('min-24', 'mind', 'Digital sunset: charge your phone outside your room', 'Use a cheap alarm clock or keep the volume up from the next room.', 5, 'free', 'none', 2, array['phoenix']::text[], 3, array['phone', 'energy']::text[], null),
  ('min-25', 'mind', 'Write a letter to yourself on Day 90', 'What you want to be true by then, and what you''ll say no to on the way.', 10, 'free', 'none', 1, '{}'::text[], 3, '{}'::text[], null),
  ('min-26', 'mind', 'Read 20 pages', 'Somewhere quiet, phone on silent. Write one line you want to remember.', 30, 'free', 'none', 2, '{}'::text[], 3, '{}'::text[], null),
  ('min-27', 'mind', 'Finish one thing you started and left', 'A form, an assignment, a course module. Done beats perfect.', 30, 'free', 'none', 3, array['phoenix']::text[], 3, array['focus']::text[], null),
  ('min-28', 'mind', 'Write three specific things you''re grateful for', 'Specific beats general: "Amma packed lunch" rather than "family".', 5, 'free', 'none', 1, '{}'::text[], 3, '{}'::text[], null),
  ('min-29', 'mind', 'Plan the next 7 days in time blocks', 'Put your top tasks into real slots in your calendar, with breaks.', 20, 'free', 'none', 2, array['phoenix', 'strategist']::text[], 3, array['planning']::text[], null),
  ('min-30', 'mind', 'Learn a skill for 20 minutes with a free course', 'Pick one lesson and finish it. Take notes in your own words.', 20, 'free', 'none', 2, '{}'::text[], 3, '{}'::text[], null),
  ('mon-01', 'money', 'Scroll last week''s UPI history and tag your top 3 money leaks', 'Food delivery, impulse buys, small daily spends. Just name them; no guilt.', 10, 'free', 'none', 1, array['strategist']::text[], 1, '{}'::text[], null),
  ('mon-02', 'money', 'Move ₹100 into a separate savings pocket', 'If ₹100 is too much, move ₹20. The habit matters more than the amount.', 5, 'free', 'none', 1, array['strategist']::text[], 1, '{}'::text[], null),
  ('mon-03', 'money', 'List 3 skills someone would pay you for', 'Tutoring, editing, design, coding, translation. Anything you do better than most.', 5, 'free', 'none', 1, array['founder']::text[], 1, array['earn']::text[], null),
  ('mon-04', 'money', 'Write down every spend today', 'Amount and what it was for, in your notes. Even ₹10 chai counts.', 5, 'free', 'none', 1, array['strategist']::text[], 1, '{}'::text[], null),
  ('mon-05', 'money', 'Find one subscription you don''t use', 'Check app stores, UPI autopay and your bank SMS. Cancel it or set a reminder to.', 5, 'free', 'none', 1, array['strategist']::text[], 1, '{}'::text[], null),
  ('mon-06', 'money', 'Set a weekly spending cap', 'Pick one number for food and fun this week. Write it where you''ll see it.', 5, 'free', 'none', 1, array['strategist']::text[], 1, array['planning']::text[], null),
  ('mon-07', 'money', 'Find out what your bank charges you', 'Check your bank app or SMS for fees: minimum balance, SMS alerts, card charges.', 10, 'free', 'none', 1, '{}'::text[], 1, '{}'::text[], null),
  ('mon-08', 'money', 'Make a simple monthly budget', 'Money in, fixed costs, savings first, then what''s left for everything else.', 20, 'free', 'none', 2, array['strategist']::text[], 1, array['planning']::text[], null),
  ('mon-09', 'money', 'Ask 3 people what they''d pay for one of your skills', 'Friends, seniors or local shops. Ask about the problem first, then the price.', 20, 'free', 'none', 2, array['founder']::text[], 1, array['earn']::text[], null),
  ('mon-10', 'money', 'Learn three common UPI scams', 'You never need your PIN or an OTP to receive money, and a collect request takes money out.', 10, 'free', 'none', 1, '{}'::text[], 1, '{}'::text[], null),
  ('mon-11', 'money', 'No-spend day: essentials only', 'Food you''d eat anyway, travel and bills are fine. Skip everything else for one day.', 5, 'free', 'none', 2, array['strategist']::text[], 2, '{}'::text[], null),
  ('mon-12', 'money', 'Compare prices before one purchase', 'Check two shops or apps before you pay. Note what you saved.', 5, 'free', 'none', 1, '{}'::text[], 2, '{}'::text[], null),
  ('mon-13', 'money', 'Write a one-line offer for your skill', 'Who it''s for, what you do, the price. For example: "Resume formatting for freshers, ₹199."', 10, 'free', 'none', 2, array['founder']::text[], 2, array['earn']::text[], null),
  ('mon-14', 'money', 'Cook or carry one meal instead of ordering', 'Compare it with what the delivery would have cost and note the difference.', 20, 'low', 'none', 1, array['strategist']::text[], 2, '{}'::text[], null),
  ('mon-15', 'money', 'Check your spends against your weekly cap', 'Add up this week so far. If you''re over, pick one spend to skip.', 5, 'free', 'none', 1, array['strategist']::text[], 2, '{}'::text[], null),
  ('mon-16', 'money', 'Set an emergency-fund target', 'Add up one month of essentials: rent or hostel, food, travel, phone. That''s your first target.', 10, 'free', 'none', 2, array['strategist']::text[], 2, '{}'::text[], null),
  ('mon-17', 'money', 'Share your offer in one group you''re already in', 'A college, hostel or community group where it''s allowed. One clear message, no spam.', 10, 'free', 'none', 2, array['founder']::text[], 2, array['earn']::text[], null),
  ('mon-18', 'money', 'Sell or give away one thing you don''t use', 'Old books, gadgets or clothes. List it today; done is better than the perfect price.', 20, 'free', 'none', 2, '{}'::text[], 2, array['earn']::text[], null),
  ('mon-19', 'money', 'Do one small paid task', 'Tutoring, a design, a small fix for someone. Agree the price before you start.', 45, 'free', 'none', 3, array['founder']::text[], 2, array['earn']::text[], null),
  ('mon-20', 'money', 'Note one thing you didn''t buy today', 'Write what you skipped and what it would have cost. It adds up.', 5, 'free', 'none', 1, '{}'::text[], 2, '{}'::text[], null),
  ('mon-21', 'money', 'Make one small saving automatic', 'Set a monthly reminder or a standing instruction for a small amount on the day money comes in.', 10, 'free', 'none', 2, array['strategist']::text[], 3, '{}'::text[], null),
